const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("expired link answers 410 and the click is not recorded", async () => {
  const { base, close } = startServer();
  try {
    const past = new Date(Date.now() - 60_000).toISOString();
    const created = await api(base, "POST", "/api/links", {
      url: "https://example.com/old",
      slug: "bygone",
      expiresAt: past,
    });
    assert.strictEqual(created.status, 201);
    assert.strictEqual(created.json.expiresAt, past);

    const hit = await api(base, "GET", "/r/bygone");
    assert.strictEqual(hit.status, 410);
    assert.deepStrictEqual(hit.json, { error: "link expired" });

    const stats = await api(base, "GET", "/api/links/bygone/stats");
    assert.strictEqual(stats.json.total, 0, "an expired hit must not count as a click");

    // metadata stays readable after expiry
    assert.strictEqual((await api(base, "GET", "/api/links/bygone")).status, 200);
  } finally {
    await close();
  }
});

test("future expiry still redirects and counts", async () => {
  const { base, close } = startServer();
  try {
    const future = new Date(Date.now() + 3_600_000).toISOString();
    await api(base, "POST", "/api/links", {
      url: "https://example.com/fresh",
      slug: "fresh",
      expiresAt: future,
    });
    const hit = await api(base, "GET", "/r/fresh");
    assert.strictEqual(hit.status, 302);
    assert.strictEqual(hit.headers.get("location"), "https://example.com/fresh");
    const stats = await api(base, "GET", "/api/links/fresh/stats");
    assert.strictEqual(stats.json.total, 1);
  } finally {
    await close();
  }
});

test("links without expiry behave as before", async () => {
  const { base, close } = startServer();
  try {
    await api(base, "POST", "/api/links", { url: "https://example.com", slug: "forever" });
    assert.strictEqual((await api(base, "GET", "/r/forever")).status, 302);
  } finally {
    await close();
  }
});

test("malformed expiresAt is rejected", async () => {
  const { base, close } = startServer();
  try {
    const bad = await api(base, "POST", "/api/links", {
      url: "https://example.com",
      slug: "soonish",
      expiresAt: "next tuesday",
    });
    assert.strictEqual(bad.status, 400);
  } finally {
    await close();
  }
});

